/// A problem in a file, as elm reports it.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Diagnostic {
    pub range: TextRange,
    pub title: String,
    /// The message as the terminal shows it, without styles.
    pub message: String,
}

/// A change to a file's text: what replaces `range`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Edit {
    pub range: TextRange,
    pub text: String,
}

impl Edit {
    /// `range` taken out.
    fn delete(range: TextRange) -> Edit {
        Edit {
            range,
            text: String::new(),
        }
    }

    /// `text` put in at `at`.
    fn insert(at: TextSize, text: String) -> Edit {
        Edit {
            range: TextRange::empty(at),
            text,
        }
    }
}

/// Each file's edits, the files in the order they first had one.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct FileEdits<E = Edit>(Vec<(PathBuf, Vec<E>)>);

impl<E> FileEdits<E> {
    /// `edits` of the file at `path`.
    fn of(path: &Path, edits: Vec<E>) -> FileEdits<E> {
        FileEdits(vec![(path.to_owned(), edits)])
    }

    /// The edits of the file at `path` so far, none where it has none.
    fn file(&mut self, path: &Path) -> &mut Vec<E> {
        let at = if let Some(at) = self.0.iter().position(|(p, _)| p == path) {
            at
        } else {
            self.0.push((path.to_owned(), Vec::new()));
            self.0.len() - 1
        };
        &mut self.0[at].1
    }

    /// `other`'s edits after those each file has (`Utils.mergeChanges`).
    fn merge(&mut self, other: FileEdits<E>) {
        for (path, edits) in other {
            self.file(&path).extend(edits);
        }
    }

    fn iter(&self) -> std::slice::Iter<'_, (PathBuf, Vec<E>)> {
        self.0.iter()
    }
}

impl<E> Default for FileEdits<E> {
    fn default() -> FileEdits<E> {
        FileEdits(Vec::new())
    }
}

impl<E> IntoIterator for FileEdits<E> {
    type Item = (PathBuf, Vec<E>);
    type IntoIter = std::vec::IntoIter<(PathBuf, Vec<E>)>;

    fn into_iter(self) -> Self::IntoIter {
        self.0.into_iter()
    }
}

impl<'f, E> IntoIterator for &'f mut FileEdits<E> {
    type Item = &'f mut (PathBuf, Vec<E>);
    type IntoIter = std::slice::IterMut<'f, (PathBuf, Vec<E>)>;

    fn into_iter(self) -> Self::IntoIter {
        self.0.iter_mut()
    }
}

impl<'f, E> IntoIterator for &'f FileEdits<E> {
    type Item = &'f (PathBuf, Vec<E>);
    type IntoIter = std::slice::Iter<'f, (PathBuf, Vec<E>)>;

    fn into_iter(self) -> Self::IntoIter {
        self.0.iter()
    }
}

/// How many characters `offset` is past the start of its line in `text`.
fn column(text: &str, offset: TextSize) -> usize {
    let before = &text[..usize::from(offset)];
    let line = before.rfind('\n').map_or(0, |i| i + 1);
    before[line..].chars().count()
}

/// Where the line after the one `offset` is on starts in `text`, or its
/// end where that's the last.
fn next_line(text: &str, offset: TextSize) -> TextSize {
    let at = usize::from(offset);
    let next = text[at..].find('\n').map_or(text.len(), |i| at + i + 1);
    TextSize::new(next as u32)
}

/// Where the last line of `text` starts.
fn last_line(text: &str) -> TextSize {
    TextSize::new(text.rfind('\n').map_or(0, |i| i + 1) as u32)
}

/// How the project that owns a file reads it: the release its `elm.json`
/// names and what kind of source the file is. A file in no project is
/// read as an application of the newest release.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Context {
    compat: Compat,
    source: nomi_syntax::Source,
}

impl Context {
    /// The context of the file at `path`, from the nearest `elm.json`
    /// above it (R7).
    fn of(snapshot: &Snapshot, path: &Path) -> Context {
        let manifest = manifest(snapshot, path).and_then(|m| snapshot.read_bytes(&m).ok());
        match manifest.map(|bytes| Outline::detect(&bytes)) {
            Some(Ok((Outline::App(_), compat))) => Context {
                compat,
                source: nomi_syntax::Source::Application,
            },
            Some(Ok((Outline::Pkg(pkg), compat))) => Context {
                compat,
                source: if pkg.name.is_kernel() {
                    nomi_syntax::Source::Kernel
                } else {
                    nomi_syntax::Source::Package
                },
            },
            Some(Err(_)) | None => Context {
                compat: Compat::LATEST,
                source: nomi_syntax::Source::Application,
            },
        }
    }
}

/// The syntax error elm reports for the file at `path`, if any, at the
/// region it reports.
pub fn diagnostics(snapshot: &Snapshot, path: &Path) -> io::Result<Vec<Diagnostic>> {
    let text = snapshot.read(path)?;
    let context = Context::of(snapshot, path);
    let parse = parse_module(&text);
    let mut errors = parse.errors().to_vec();
    errors.extend(validate(&parse, Tool::Elm(context.source, context.compat)));
    if errors.is_empty() {
        return Ok(Vec::new());
    }
    errors.sort_by_key(|e| e.range.start());
    let problem = syntax_problem(&text, &errors, context.source, context.compat);
    let range = elm_range(
        &text,
        &LineIndex::new(&text),
        problem.region,
        context.compat,
    );
    Ok(vec![Diagnostic {
        range,
        title: problem.title.into_owned(),
        message: render::render(&problem.message, context.compat, 80, Styles::Plain)
            .trim_end()
            .to_owned(),
    }])
}

/// The range of `text`, whose lines are `lines`, that a region as
/// `compat` keeps it covers: past a line's end at the line's end, past
/// the text at its end, and never ending before it starts.
fn elm_range(text: &str, lines: &LineIndex, region: Region, compat: Compat) -> TextRange {
    let first = compat.first_position();
    let offset = |at: Position| {
        let at = LineCol {
            line: at.row.saturating_sub(first),
            col: at.col.saturating_sub(first),
        };
        lines.elm_offset(text, at)
    };
    let start = offset(region.start);
    TextRange::new(start, offset(region.end).max(start))
}

/// The edits that format the file at `path` as elm-format does, each as
/// small as the lines that change allow; `None` where elm-format rejects
/// the file.
pub fn format(snapshot: &Snapshot, path: &Path) -> io::Result<Option<Vec<Edit>>> {
    let text = snapshot.read(path)?;
    Ok(nomi_format::format(&text).map(|formatted| edits(&text, &formatted)))
}

/// The edits that turn `before` into `after`: one per run of changed
/// lines, without the characters the run keeps at its ends.
fn edits(before: &str, after: &str) -> Vec<Edit> {
    let diff = similar::TextDiff::from_lines(before, after);
    let starts = |text: &str| {
        let mut starts = vec![0];
        starts.extend(text.match_indices('\n').map(|(i, _)| i + 1));
        starts.push(text.len());
        starts
    };
    let (old_lines, new_lines) = (starts(before), starts(after));
    let line_start = |starts: &[usize], line: usize| starts[line.min(starts.len() - 1)];
    let mut edits = Vec::new();
    for op in diff.ops() {
        if let similar::DiffOp::Equal { .. } = op {
            continue;
        }
        let (old, new) = (op.old_range(), op.new_range());
        let mut old = line_start(&old_lines, old.start)..line_start(&old_lines, old.end);
        let mut new = line_start(&new_lines, new.start)..line_start(&new_lines, new.end);
        let (a, b) = (&before[old.clone()], &after[new.clone()]);
        let prefix = common(a.chars().zip(b.chars()));
        old.start += prefix;
        new.start += prefix;
        let (a, b) = (&before[old.clone()], &after[new.clone()]);
        let suffix = common(a.chars().rev().zip(b.chars().rev()));
        old.end -= suffix;
        new.end -= suffix;
        edits.push(Edit {
            range: TextRange::new(
                TextSize::new(old.start as u32),
                TextSize::new(old.end as u32),
            ),
            text: after[new].to_owned(),
        });
    }
    edits
}

/// How many bytes the pairs of characters `pairs` start with are equal
/// for.
fn common(pairs: impl Iterator<Item = (char, char)>) -> usize {
    pairs
        .take_while(|(x, y)| x == y)
        .map(|(x, _)| x.len_utf8())
        .sum()
}

